 let native:any={type:{id:1249}};const client:any={ingame:true,ifType:()=>({colour:0x00f800}),membersAccount:1,selfSlot:1,executeBotAction:()=>({success:true}),mapBuildBaseX:0,mapBuildBaseZ:0,minusedlevel:0,localPlayer:{routeX:[3510],routeZ:[3480],routeLength:0},npc:[],objType:(id:number)=>({certtemplate:-1,stackable:id===995||id===2958,cost:1})};
 const add=(a:any[],id:number,n:number)=>{if(mode==='ledger-eight'&&a===inv&&id===2434){for(let i=0;i<n;i++)a.push({id,count:1,slot:a.length});return;}const row=a.find(i=>i.id===id);if(row)row.count+=n;else a.push({id,count:n,slot:a.length});};
 const move=(p:any)=>{player.worldX=p.x;player.worldZ=p.z;client.localPlayer.routeX[0]=p.x;client.localPlayer.routeZ[0]=p.z;client.localPlayer.routeLength=0;};
